package com.project.w_3d_world.features.wallet.controller;
import com.project.w_3d_world.common.config.AuthenticatedUser; import com.project.w_3d_world.common.response.ApiResponse; import com.project.w_3d_world.features.wallet.dto.WalletDtos.*; import com.project.w_3d_world.features.wallet.service.WalletService; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor @PreAuthorize("isAuthenticated()") @SecurityRequirement(name="bearerAuth") @Tag(name="Seller wallet",description="Pending, available and payout-hold balances with idempotent ledger entries.")
public class WalletController { private final WalletService service; @GetMapping("/users/me/wallet") @Operation(summary="Get wallet",description="Return pending revenue, available balance, payout hold and seller earning commission snapshots.") public ApiResponse<WalletResponse> mine(@AuthenticationPrincipal AuthenticatedUser user){return ApiResponse.success(service.mine(user.userId()));} @PostMapping("/users/me/payouts") @Operation(summary="Request payout",description="Lock available balance against a verified bank account. Admin must approve or reject; at least 100000 VND must remain available and shipping debt must be cleared.") public ApiResponse<PayoutResponse> request(@AuthenticationPrincipal AuthenticatedUser user,@Valid @RequestBody PayoutRequest request){return ApiResponse.success(service.request(user.userId(),request));} @PatchMapping("/admin/payouts/{id}") @Operation(summary="Decide payout",description="Admin approves manual transfer or rejects it; held funds are spent or returned exactly once.") public ApiResponse<PayoutResponse> decide(@AuthenticationPrincipal AuthenticatedUser user,@PathVariable int id,@Valid @RequestBody PayoutDecision request){return ApiResponse.success(service.decide(user.userId(),id,request));} }
